def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - np.fmax(0, bins - item)
    return remaining

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    target_fraction = 0.5
    remaining = bins - item
    target = bins * target_fraction
    return -np.abs(remaining - target)
